1	<!DOCTYPE html>
2	<html lang="zh-CN">
3	<head>
4	<meta charset="UTF-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1.0, user-scalable=no">
6	<title>轨道跑者 — Rail Runner</title>
7	<style>
8	  * { margin:0; padding:0; box-sizing:border-box; }
9	  html, body { width:100%; height:100%; overflow:hidden; background:#1a1a2e; }
10	  body {
11	    display:flex; justify-content:center; align-items:center;
12	    font-family:'Segoe UI','PingFang SC',sans-serif;
13	  }
14	  #game-container {
15	    position:relative;
16	    width:100vmin; max-width:600px;
17	    height:100vmin; max-height:900px;
18	    aspect-ratio:2/3;
19	  }
20	  canvas {
21	    display:block; width:100%; height:100%;
22	    touch-action:manipulation;
23	    image-rendering:auto;
24	  }
25	</style>
26	</head>
27	<body>
28	
29	<div id="game-container">
30	  <canvas id="game"></canvas>
31	</div>
32	
33	<script>
34	/* ==========================================================================
35	   轨道跑者 — Rail Runner  v0.1 Tier 1
36	   2.5D 等距视角无限跑酷 | HTML5 Canvas | 60fps | 零依赖
37	   ========================================================================== */
38	
39	/* =========================== 命名空间 =========================== */
40	const G = {
41	  canvas: null,
42	  ctx: null,
43	  W: 0, H: 0,
44	
45	  /* 游戏状态 */
46	  state: 'start',     // start | playing | dead
47	  score: 0,
48	  highScore: 0,
49	  coinScore: 0,         // 累计金币分数（防止被距离分覆盖）
50	  distance: 0,
51	  speed: 0,
52	  hearts: 3,
53	  invincible: 0,       // 剩余无敌帧数
54	
55	  /* 玩家 */
56	  player: null,
57	
58	  /* 对象池 */
59	  obstacles: [],
60	  coins: [],
61	  particles: [],
62	  powerups: [],
63	
64	  /* 输入 */
65	  keys: {},
66	  swipeStart: null,
67	  lastSwipe: '',
68	
69	  /* 屏幕震动 */
70	  shakeX: 0,
71	  shakeY: 0,
72	  shakeDuration: 0,
73	  flashAlpha: 0,
74	
75	  /* 世界参数 */
76	  vanishY: 0,          // 消失点 Y
77	  vanishX: 0,          // 消失点 X
78	  maxDist: 800,        // 最大可视距离
79	  laneSpread: 0,       // 轨道底部扩散宽度
80	  groundY: 0,          // 玩家地面位置 Y（屏幕坐标）
81	
82	  /* 生成控制 */
83	  spawnTimer: 0,
84	  spawnInterval: 60,   // 初始帧间隔
85	  coinTimer: 0,
86	
87	  /* 帧率 */
88	  lastTime: 0,
89	  deltaTime: 0,
90	  fps: 0,
91	  frameCount: 0,
92	  fpsTime: 0,
93	
94	  /* 离线画布 */
95	  offscreen: {},
96	
97	  /* 音效 */
98	  audioCtx: null,
99	  audioReady: false,
100	};
101	
102	/* =========================== 常量 =========================== */
103	const LANE_COUNT = 3;
104	const PLAYER_LANE = 1;     // 玩家初始在中间轨道 (0=左, 1=中, 2=右)
105	const MAX_HEARTS = 3;
106	const INVINCIBLE_FRAMES = 90;  // 1.5秒 @ 60fps
107	const BASE_SPEED = 3.5;
108	const MAX_SPEED = 14;
109	const SPEED_INC = 0.0004;      // 每帧加速量
110	const DISTANCE_PER_FRAME = 0.6; // 每帧距离增量（米）
111	const COIN_SCORE = 50;
112	const DISTANCE_SCORE = 1;       // 每米分数
113	
114	/* 玩家动作状态 */
115	const STATE_RUN = 'run';
116	const STATE_JUMP = 'jump';
117	const STATE_SLIDE = 'slide';
118	const STATE_HIT = 'hit';
119	
120	/* 障碍物类型 */
121	const OBS_LOW = 'low';       // 滑铲通过
122	const OBS_MID = 'mid';       // 跳跃通过
123	const OBS_HIGH = 'high';     // 必须换道
124	
125	/* 道具类型 */
126	const PUP_MAGNET = 'magnet';   // 磁铁：自动吸金币
127	const PUP_SHIELD = 'shield';   // 护盾：额外承受一次伤害
128	const PUP_2X = '2x';           // 双倍分数
129	
130	const POWERUP_DURATION = 480;  // 道具持续时间 8秒 @ 60fps
131	const MAGNET_RANGE = 1.5;      // 磁铁吸金币范围（轨道单位）
132	
133	/* =========================== 工具函数 =========================== */
134	function lerp(a, b, t) { return a + (b - a) * t; }
135	function clamp(v, lo, hi) { return v < lo ? lo : v > hi ? hi : v; }
136	function randInt(min, max) { return Math.floor(Math.random() * (max - min + 1)) + min; }
137	function randChoice(arr) { return arr[Math.floor(Math.random() * arr.length)]; }
138	
139	/* =========================== Web Audio 音效系统 =========================== */
140	/** 初始化 AudioContext（需在首次用户交互后调用） */
141	function initAudio() {
142	  if (G.audioReady) return;
143	  try {
144	    G.audioCtx = new (window.AudioContext || window.webkitAudioContext)();
145	    G.audioReady = true;
146	  } catch(e) {
147	    G.audioReady = false;
148	  }
149	}
150	
151	/** 播放一个简单的合成音效 */
152	function playSound(freq, type, duration, vol, options) {
153	  if (!G.audioReady) return;
154	  const ctx = G.audioCtx;
155	  const opts = options || {};
156	  const now = ctx.currentTime;
157	
158	  const osc = ctx.createOscillator();
159	  const gain = ctx.createGain();
160	  osc.type = type || 'sine';
161	  osc.frequency.setValueAtTime(freq, now);
162	  if (opts.freqEnd) osc.frequency.linearRampToValueAtTime(opts.freqEnd, now + duration);
163	  gain.gain.setValueAtTime(vol || 0.15, now);
164	  gain.gain.exponentialRampToValueAtTime(0.001, now + duration);
165	  osc.connect(gain);
166	  gain.connect(ctx.destination);
167	  osc.start(now);
168	  osc.stop(now + duration);
169	}
170	
171	/** 噪音发生器——用于滑铲、撞击等 */
172	function playNoise(duration, vol, filterFreq) {
173	  if (!G.audioReady) return;
174	  const ctx = G.audioCtx;
175	  const now = ctx.currentTime;
176	  const bufferSize = Math.floor(ctx.sampleRate * duration);
177	  const buffer = ctx.createBuffer(1, bufferSize, ctx.sampleRate);
178	  const data = buffer.getChannelData(0);
179	  for (let i = 0; i < bufferSize; i++) {
180	    data[i] = (Math.random() * 2 - 1) * (1 - i / bufferSize); // 衰减包络
181	  }
182	  const source = ctx.createBufferSource();
183	  source.buffer = buffer;
184	  const gain = ctx.createGain();
185	  gain.gain.setValueAtTime(vol || 0.1, now);
186	  gain.gain.exponentialRampToValueAtTime(0.001, now + duration);
187	
188	  let node = source;
189	  if (filterFreq) {
190	    const filter = ctx.createBiquadFilter();
191	    filter.type = 'lowpass';
192	    filter.frequency.setValueAtTime(filterFreq, now);
193	    source.connect(filter);
194	    node = filter;
195	  }
196	  node.connect(gain);
197	  gain.connect(ctx.destination);
198	  source.start(now);
199	  source.stop(now + duration);
200	}
201	
202	/* 各音效快捷函数 */
203	function sfxJump() {
204	  playSound(350, 'square', 0.15, 0.08, { freqEnd: 700 });
205	}
206	
207	function sfxSlide() {
208	  playNoise(0.12, 0.06, 800);
209	}
210	
211	function sfxCoin() {
212	  if (!G.audioReady) return;
213	  const ctx = G.audioCtx;
214	  const now = ctx.currentTime;
215	  [880, 1320].forEach((f, i) => {
216	    const osc = ctx.createOscillator();
217	    const gain = ctx.createGain();
218	    osc.type = 'square';
219	    osc.frequency.setValueAtTime(f, now + i * 0.06);
220	    gain.gain.setValueAtTime(0.06, now + i * 0.06);
221	    gain.gain.exponentialRampToValueAtTime(0.001, now + i * 0.06 + 0.1);
222	    osc.connect(gain);
223	    gain.connect(ctx.destination);
224	    osc.start(now + i * 0.06);
225	    osc.stop(now + i * 0.06 + 0.1);
226	  });
227	}
228	
229	function sfxHurt() {
230	  if (!G.audioReady) return;
231	  const ctx = G.audioCtx;
232	  const now = ctx.currentTime;
233	  /* 低频撞击 + 噪音 */
234	  const osc = ctx.createOscillator();
235	  const gain = ctx.createGain();
236	  osc.type = 'triangle';
237	  osc.frequency.setValueAtTime(120, now);
238	  osc.frequency.exponentialRampToValueAtTime(40, now + 0.2);
239	  gain.gain.setValueAtTime(0.15, now);
240	  gain.gain.exponentialRampToValueAtTime(0.001, now + 0.2);
241	  osc.connect(gain);
242	  gain.connect(ctx.destination);
243	  osc.start(now);
244	  osc.stop(now + 0.2);
245	  playNoise(0.1, 0.08, 300);
246	}
247	
248	function sfxDeath() {
249	  if (!G.audioReady) return;
250	  const ctx = G.audioCtx;
251	  const now = ctx.currentTime;
252	  /* 下降音阶 */
253	  [400, 300, 200, 120].forEach((f, i) => {
254	    const osc = ctx.createOscillator();
255	    const gain = ctx.createGain();
256	    osc.type = 'sawtooth';
257	    osc.frequency.setValueAtTime(f, now + i * 0.12);
258	    gain.gain.setValueAtTime(0.1, now + i * 0.12);
259	    gain.gain.exponentialRampToValueAtTime(0.001, now + i * 0.12 + 0.15);
260	    osc.connect(gain);
261	    gain.connect(ctx.destination);
262	    osc.start(now + i * 0.12);
263	    osc.stop(now + i * 0.12 + 0.15);
264	  });
265	  playNoise(0.25, 0.12, 200);
266	}
267	
268	function sfxPowerup() {
269	  if (!G.audioReady) return;
270	  const ctx = G.audioCtx;
271	  const now = ctx.currentTime;
272	  /* 上行琶音 */
273	  [440, 554, 659, 880].forEach((f, i) => {
274	    const osc = ctx.createOscillator();
275	    const gain = ctx.createGain();
276	    osc.type = 'sine';
277	    osc.frequency.setValueAtTime(f, now + i * 0.08);
278	    gain.gain.setValueAtTime(0.08, now + i * 0.08);
279	    gain.gain.exponentialRampToValueAtTime(0.001, now + i * 0.08 + 0.15);
280	    osc.connect(gain);
281	    gain.connect(ctx.destination);
282	    osc.start(now + i * 0.08);
283	    osc.stop(now + i * 0.08 + 0.15);
284	  });
285	}
286	
287	/* 屏幕坐标：根据世界深度计算 screenY 和缩放比例 */
288	function worldToScreen(dist) {
289	  /* dist: 0 = 玩家脚下, maxDist = 地平线 */
290	  const t = 1 - clamp(dist / G.maxDist, 0, 1);
291	  const screenY = lerp(G.vanishY, G.groundY, t);
292	  const scale = lerp(0.15, 1.0, t);
293	  return { y: screenY, scale };
294	}
295	
296	/* 轨道 X 坐标：根据深度 + 轨道索引计算 screenX */
297	function laneX(laneIdx, dist) {
298	  const t = 1 - clamp(dist / G.maxDist, 0, 1);
299	  const spread = lerp(0, G.laneSpread, t);
300	  const centerX = G.vanishX;
301	  return centerX + (laneIdx - 1) * spread;
302	}
303	
304	/* =========================== 初始化 =========================== */
305	function init() {
306	  G.canvas = document.getElementById('game');
307	  G.ctx = G.canvas.getContext('2d', { alpha: false });
308	  resize();
309	  window.addEventListener('resize', resize);
310	
311	  /* 加载最高分 */
312	  try {
313	    G.highScore = parseInt(localStorage.getItem('railRunner_highScore')) || 0;
314	  } catch(e) { G.highScore = 0; }
315	
316	  /* 输入：键盘 */
317	  window.addEventListener('keydown', e => {
318	    G.keys[e.key] = true;
319	    if (e.key === ' ' || e.key === 'ArrowUp' || e.key === 'ArrowDown') {
320	      e.preventDefault();
321	    }
322	    if (G.state === 'start' && e.key === ' ') startGame();
323	    if (G.state === 'dead' && e.key === ' ') restartGame();
324	  });
325	  window.addEventListener('keyup', e => { G.keys[e.key] = false; });
326	
327	  /* 输入：触屏 */
328	  G.canvas.addEventListener('touchstart', e => {
329	    e.preventDefault();
330	    if (G.state === 'start') { startGame(); return; }
331	    if (G.state === 'dead') { restartGame(); return; }
332	    const t = e.touches[0];
333	    G.swipeStart = { x: t.clientX, y: t.clientY, time: Date.now() };
334	  }, { passive: false });
335	
336	  G.canvas.addEventListener('touchend', e => {
337	    if (!G.swipeStart) return;
338	    const t = e.changedTouches[0];
339	    const dx = t.clientX - G.swipeStart.x;
340	    const dy = t.clientY - G.swipeStart.y;
341	    const dt = Date.now() - G.swipeStart.time;
342	    const absDx = Math.abs(dx), absDy = Math.abs(dy);
343	
344	    if (Math.max(absDx, absDy) < 20) return; // 太小忽略
345	
346	    if (absDx > absDy) {
347	      G.lastSwipe = dx > 0 ? 'right' : 'left';
348	    } else {
349	      G.lastSwipe = dy > 0 ? 'down' : 'up';
350	    }
351	    G.swipeStart = null;
352	  });
353	
354	  /* 玩家 */
355	  G.player = createPlayer();
356	
357	  /* 预渲染 */
358	  preRenderAssets();
359	
360	  /* 启动循环 */
361	  G.lastTime = performance.now();
362	  requestAnimationFrame(gameLoop);
363	}
364	
365	function resize() {
366	  const container = document.getElementById('game-container');
367	  const rect = container.getBoundingClientRect();
368	  const dpr = Math.min(window.devicePixelRatio || 1, 2); // 限制像素比
369	  G.W = rect.width;
370	  G.H = rect.height;
371	  G.canvas.width = G.W * dpr;
372	  G.canvas.height = G.H * dpr;
373	  G.canvas.style.width = G.W + 'px';
374	  G.canvas.style.height = G.H + 'px';
375	  G.ctx.setTransform(1, 0, 0, 1, 0, 0);
376	  G.ctx.scale(dpr, dpr);
377	
378	  /* 重新计算透视参数 */
379	  G.vanishX = G.W * 0.5;
380	  G.vanishY = G.H * 0.28;
381	  G.groundY = G.H * 0.88;
382	  G.laneSpread = G.W * 0.18;
383	
384	  /* 预渲染需要 resize */
385	  preRenderAssets();
386	}
387	
388	/* =========================== 预渲染资源 =========================== */
389	function preRenderAssets() {
390	  /* --- 天空渐变背景 --- */
391	  const skyCanvas = document.createElement('canvas');
392	  skyCanvas.width = G.W;
393	  skyCanvas.height = G.H;
394	  const skyCtx = skyCanvas.getContext('2d');
395	  const grad = skyCtx.createLinearGradient(0, 0, 0, G.vanishY + 40);
396	  grad.addColorStop(0, '#1a1a4e');
397	  grad.addColorStop(0.5, '#2d4a8e');
398	  grad.addColorStop(1, '#5ba3d9');
399	  skyCtx.fillStyle = grad;
400	  skyCtx.fillRect(0, 0, G.W, G.H);
401	  /* 云层 */
402	  skyCtx.fillStyle = 'rgba(255,255,255,0.08)';
403	  for (let ci = 0; ci < 8; ci++) {
404	    const cx = Math.random() * G.W;
405	    const cy = Math.random() * G.vanishY * 0.7;
406	    const cw = 60 + Math.random() * 120;
407	    skyCtx.beginPath();
408	    skyCtx.ellipse(cx, cy, cw, 12 + Math.random() * 10, 0, 0, Math.PI * 2);
409	    skyCtx.fill();
410	    skyCtx.beginPath();
411	    skyCtx.ellipse(cx + cw*0.3, cy - 8, cw*0.6, 10 + Math.random() * 8, 0, 0, Math.PI * 2);
412	    skyCtx.fill();
413	  }
414	  G.offscreen.sky = skyCanvas;
415	
416	  /* --- 城市天际线（远景） --- */
417	  const cityCanvas = document.createElement('canvas');
418	  cityCanvas.width = G.W * 3; // 宽于屏幕用于视差滚动
419	  cityCanvas.height = G.H * 0.25;
420	  const cityCtx = cityCanvas.getContext('2d');
421	  /* 建筑剪影 */
422	  cityCtx.fillStyle = '#1a1a3e';
423	  const buildings = [];
424	  let bx = 0;
425	  while (bx < cityCanvas.width) {
426	    const bw = randInt(30, 100);
427	    const bh = randInt(40, cityCanvas.height * 0.85);
428	    buildings.push({ x: bx, w: bw, h: bh });
429	    bx += bw + randInt(5, 20);
430	  }
431	  buildings.forEach(b => {
432	    cityCtx.fillRect(b.x, cityCanvas.height - b.h, b.w, b.h);
433	    /* 远处涂鸦（简化色块） */
434	    if (Math.random() < 0.2 && b.w > 50) {
435	      const tagColors = ['#ff3366','#ff6600','#33ff66','#33ccff','#ff33cc'];
436	      cityCtx.fillStyle = tagColors[Math.floor(Math.random() * tagColors.length)];
437	      cityCtx.fillRect(b.x + 8, cityCanvas.height - b.h + 10, b.w - 16, 8);
438	    }
439	    /* 窗户光点 */
440	    cityCtx.fillStyle = 'rgba(255,220,150,0.3)';
441	    for (let wy = cityCanvas.height - b.h + 8; wy < cityCanvas.height - 8; wy += 12) {
442	      for (let wx = b.x + 6; wx < b.x + b.w - 6; wx += 10) {
443	        if (Math.random() < 0.4) cityCtx.fillRect(wx, wy, 3, 3);
444	      }
445	    }
446	    cityCtx.fillStyle = '#1a1a3e';
447	  });
448	  G.offscreen.city = cityCanvas;
449	
450	  /* --- 近景建筑（更大、暖色调） --- */
451	  const nearCanvas = document.createElement('canvas');
452	  nearCanvas.width = G.W * 2;
453	  nearCanvas.height = G.H * 0.35;
454	  const nearCtx = nearCanvas.getContext('2d');
455	  nearCtx.fillStyle = '#2a1a0a';
456	  let nx = 0;
457	  while (nx < nearCanvas.width) {
458	    const nw = randInt(60, 160);
459	    const nh = randInt(80, nearCanvas.height * 0.9);
460	    nearCtx.fillRect(nx, nearCanvas.height - nh, nw, nh);
461	    /* 更大更亮的窗户 */
462	    nearCtx.fillStyle = 'rgba(255,200,100,0.2)';
463	    for (let wy = nearCanvas.height - nh + 12; wy < nearCanvas.height - 10; wy += 16) {
464	      for (let wx = nx + 10; wx < nx + nw - 10; wx += 14) {
465	        if (Math.random() < 0.35) nearCtx.fillRect(wx, wy, 5, 6);
466	      }
467	    }
468	    /* 随机涂鸦标签（30%几率） */
469	    if (Math.random() < 0.3) {
470	      const tagW = randInt(30, nw - 10);
471	      const tagH = randInt(20, Math.min(60, nh - 20));
472	      const tagX = nx + randInt(5, nw - tagW - 5);
473	      const tagY = nearCanvas.height - nh + randInt(10, nh - tagH - 10);
474	      drawGraffitiTag(nearCtx, tagX, tagY, tagW, tagH);
475	    }
476	    nearCtx.fillStyle = '#2a1a0a';
477	    nx += nw + randInt(8, 30);
478	  }
479	  G.offscreen.nearCity = nearCanvas;
480	
481	  /* --- 玩家精灵 预渲染 --- */
482	  G.offscreen.player = {};
483	  ['run', 'jump', 'slide', 'hit'].forEach(state => {
484	    const pc = document.createElement('canvas');
485	    pc.width = 80; pc.height = 100;
486	    drawPlayerSprite(pc.getContext('2d'), state, pc.width, pc.height);
487	    G.offscreen.player[state] = pc;
488	  });
489	
490	  /* --- 障碍物图块 --- */
491	  G.offscreen.obstacles = {};
492	  /* 低障碍（横杆） */
493	  let oc = document.createElement('canvas'); oc.width=60; oc.height=20;
494	  drawObstacleSprite(oc.getContext('2d'), OBS_LOW, oc.width, oc.height);
495	  G.offscreen.obstacles[OBS_LOW] = oc;
496	  /* 中障碍（信号灯箱） */
497	  oc = document.createElement('canvas'); oc.width=40; oc.height=55;
498	  drawObstacleSprite(oc.getContext('2d'), OBS_MID, oc.width, oc.height);
499	  G.offscreen.obstacles[OBS_MID] = oc;
500	  /* 高障碍（信号塔） */
501	  oc = document.createElement('canvas'); oc.width=50; oc.height=120;
502	  drawObstacleSprite(oc.getContext('2d'), OBS_HIGH, oc.width, oc.height);
503	  G.offscreen.obstacles[OBS_HIGH] = oc;
504	
505	  /* --- 金币 --- */
506	  const coinCanvas = document.createElement('canvas');
507	  coinCanvas.width = 32; coinCanvas.height = 32;
508	  drawCoinSprite(coinCanvas.getContext('2d'), coinCanvas.width, coinCanvas.height);
509	  G.offscreen.coin = coinCanvas;
510	
511	  /* --- 粒子 --- */
512	  const partCanvas = document.createElement('canvas');
513	  partCanvas.width = 8; partCanvas.height = 8;
514	  const partCtx = partCanvas.getContext('2d');
515	  partCtx.fillStyle = '#fff';
516	  partCtx.beginPath(); partCtx.arc(4,4,4,0,Math.PI*2); partCtx.fill();
517	  G.offscreen.particle = partCanvas;
518	}
