520	/* =========================== 精灵绘制 =========================== */
521	/* 涂鸦标签 -- 在指定位置绘制随机涂鸦 */
522	function drawGraffitiTag(ctx, x, y, w, h) {
523	  const colors = ['#ff3366','#ff6600','#ffcc00','#33ff66','#33ccff','#ff33cc','#aaff00','#ff0066'];
524	  const bgColors = ['#1a1a2e','#2a1a4e','#1a3a2e','#3a1a2e','#2a2a4e'];
525	
526	  /* 背景色块（涂鸦底板） */
527	  const bg = randChoice(bgColors);
528	  ctx.fillStyle = bg;
529	  ctx.fillRect(x, y, w, h);
530	  ctx.strokeStyle = 'rgba(255,255,255,0.2)';
531	  ctx.lineWidth = 1;
532	  ctx.strokeRect(x, y, w, h);
533	
534	  /* 涂鸦文字/图案 */
535	  const tagColor = randChoice(colors);
536	  ctx.fillStyle = tagColor;
537	
538	  /* 随机选择涂鸦风格 */
539	  const style = randInt(0, 4);
540	  const cx = x + w/2, cy = y + h/2;
541	
542	  if (style === 0) {
543	    /* 气泡字体风格 -- 重叠的圆 */
544	    ctx.globalAlpha = 0.8;
545	    for (let i = 0; i < 5; i++) {
546	      const bx = x + 10 + Math.random() * (w - 20);
547	      const by = y + 10 + Math.random() * (h - 20);
548	      const br = 8 + Math.random() * 15;
549	      ctx.beginPath(); ctx.arc(bx, by, br, 0, Math.PI*2); ctx.fill();
550	    }
551	    ctx.globalAlpha = 1;
552	  } else if (style === 1) {
553	    /* 喷漆线条 -- 粗犷的水平条纹 */
554	    ctx.lineWidth = 4 + Math.random() * 8;
555	    ctx.strokeStyle = tagColor;
556	    for (let i = 0; i < 4; i++) {
557	      ctx.beginPath();
558	      const ly = y + 10 + i * h/4;
559	      ctx.moveTo(x + 5, ly);
560	      ctx.lineTo(x + w - 5, ly + (Math.random()-0.5)*10);
561	      ctx.stroke();
562	    }
563	  } else if (style === 2) {
564	    /* 箭头/三角形涂鸦 */
565	    ctx.beginPath();
566	    ctx.moveTo(cx, cy - h*0.3);
567	    ctx.lineTo(cx + w*0.35, cy + h*0.25);
568	    ctx.lineTo(cx - w*0.35, cy + h*0.25);
569	    ctx.closePath(); ctx.fill();
570	    /* 内圈 */
571	    ctx.fillStyle = bg;
572	    ctx.beginPath(); ctx.arc(cx, cy + h*0.05, w*0.12, 0, Math.PI*2); ctx.fill();
573	  } else if (style === 3) {
574	    /* 星形/爆炸 */
575	    const spikes = randInt(5, 8);
576	    ctx.beginPath();
577	    for (let i = 0; i < spikes * 2; i++) {
578	      const r = i % 2 === 0 ? Math.min(w,h)*0.4 : Math.min(w,h)*0.15;
579	      const angle = (i / (spikes * 2)) * Math.PI * 2 - Math.PI/2;
580	      const px = cx + Math.cos(angle) * r;
581	      const py = cy + Math.sin(angle) * r;
582	      if (i === 0) ctx.moveTo(px, py);
583	      else ctx.lineTo(px, py);
584	    }
585	    ctx.closePath(); ctx.fill();
586	  } else {
587	    /* 滴落风格 -- 垂直线条 + 圆点 */
588	    const drops = randInt(3, 7);
589	    for (let i = 0; i < drops; i++) {
590	      const dx = x + w * (0.2 + Math.random() * 0.6);
591	      ctx.beginPath();
592	      ctx.moveTo(dx, y + 5);
593	      ctx.lineTo(dx, y + h * (0.3 + Math.random() * 0.5));
594	      ctx.lineWidth = 3 + Math.random() * 4;
595	      ctx.strokeStyle = randChoice(colors);
596	      ctx.stroke();
597	      ctx.beginPath();
598	      ctx.arc(dx, y + h * (0.3 + Math.random() * 0.5), 3 + Math.random()*5, 0, Math.PI*2);
599	      ctx.fillStyle = randChoice(colors);
600	      ctx.fill();
601	    }
602	  }
603	
604	  /* 白色高光/溅洒点 */
605	  ctx.fillStyle = 'rgba(255,255,255,0.4)';
606	  for (let i = 0; i < 8; i++) {
607	    const sx = x + Math.random() * w;
608	    const sy = y + Math.random() * h;
609	    ctx.beginPath(); ctx.arc(sx, sy, 1 + Math.random()*2, 0, Math.PI*2); ctx.fill();
610	  }
611	}
