799	function poolGet(pool, factory) {
800	  for (let i = 0; i < pool.length; i++) {
801	    if (!pool[i].active) { pool[i].active = true; return pool[i]; }
802	  }
803	  const obj = factory();
804	  obj.active = true;
805	  pool.push(obj);
806	  return obj;
807	}
808	
809	function poolReleaseAll(pool) {
810	  for (let i = 0; i < pool.length; i++) pool[i].active = false;
811	}
