950	/* =========================== 输入处理 =========================== */
951	function processInput() {
952	  if (G.state !== 'playing') return;
953	
954	  let moveLR = 0;
955	  let jump = false;
956	  let slide = false;
957	
958	  /* 键盘 */
959	  if (G.keys['ArrowLeft'] || G.keys['a'] || G.keys['A']) moveLR = -1;
960	  if (G.keys['ArrowRight'] || G.keys['d'] || G.keys['D']) moveLR = 1;
961	  if (G.keys['ArrowUp'] || G.keys['w'] || G.keys['W']) jump = true;
962	  if (G.keys['ArrowDown'] || G.keys['s'] || G.keys['S']) slide = true;
963	
964	  /* 触屏 */
965	  if (G.lastSwipe === 'left') { moveLR = -1; G.lastSwipe = ''; }
966	  if (G.lastSwipe === 'right') { moveLR = 1; G.lastSwipe = ''; }
967	  if (G.lastSwipe === 'up') { jump = true; G.lastSwipe = ''; }
968	  if (G.lastSwipe === 'down') { slide = true; G.lastSwipe = ''; }
969	
970	  const p = G.player;
971	  /* 换道 */
972	  if (moveLR !== 0 && p.state !== STATE_SLIDE) {
973	    p.targetLane = clamp(p.targetLane + moveLR, 0, LANE_COUNT - 1);
974	  }
975	  /* 跳跃 */
976	  if (jump && p.state === STATE_RUN) {
977	    p.state = STATE_JUMP;
978	    p.stateTimer = 28;
979	    p.jumpVel = -7;
980	    sfxJump();
981	  }
982	  /* 滑铲 */
983	  if (slide && p.state === STATE_RUN) {
984	    p.state = STATE_SLIDE;
985	    p.stateTimer = 22;
986	    sfxSlide();
987	  }
988	
989	  /* 消耗一次性按键 */
