1229	    if (obs.active && obs.lane === lane && obs.dist > G.maxDist - 100 && obs.dist < G.maxDist - 30) {
1230	      return; // 太近，跳过
1231	    }
1232	  }
1233	
1234	  poolGet(G.obstacles, () => createObstacle(0, OBS_LOW, 0));
1235	  const o = G.obstacles[G.obstacles.length - 1];
1236	  o.lane = lane;
1237	  o.type = type;
1238	  o.dist = G.maxDist;
1239	  o.passed = false;
