1541	/* =========================== 绘制金币 =========================== */
1542	function drawCoin(ctx, coin, sx, sy, scale) {
1543	  ctx.save();
1544	  ctx.translate(sx, sy);
1545	  const rot = (G.frameCount * 0.05 + coin.dist * 0.1) % (Math.PI * 2);
1546	  const squish = Math.abs(Math.cos(rot));
1547	  ctx.scale(squish * scale, scale);
1548	  ctx.fillStyle = "#ffaa00";
1549	  ctx.beginPath(); ctx.arc(0, 0, 12, 0, Math.PI * 2); ctx.fill();
1550	  ctx.fillStyle = "#ffdd44";
1551	  ctx.beginPath(); ctx.arc(0, 0, 8, 0, Math.PI * 2); ctx.fill();
1552	  ctx.fillStyle = "#ffe680";
1553	  ctx.beginPath(); ctx.arc(-2, -2, 3, 0, Math.PI * 2); ctx.fill();
1554	  ctx.restore();
1555	}
