1558	function drawPowerup(ctx, pu, sx, sy, scale) {
1559	  ctx.save();
1560	  ctx.translate(sx, sy + Math.sin(pu.floatPhase) * 4 * scale);
1561	  const sz = 14 * scale;
1562	  /* 光晕 */
1563	  ctx.shadowColor = pu.type === PUP_MAGNET ? '#ff44ff' : pu.type === PUP_SHIELD ? '#44aaff' : '#ffdd00';
1564	  ctx.shadowBlur = 10 * scale;
1565	  /* 外壳 */
1566	  ctx.fillStyle = 'rgba(255,255,255,0.85)';
1567	  ctx.beginPath();
1568	  ctx.arc(0, 0, sz, 0, Math.PI * 2);
1569	  ctx.fill();
1570	  ctx.shadowBlur = 0;
1571	  /* 图标（简化版用字母） */
1572	  ctx.fillStyle = pu.type === PUP_MAGNET ? '#ff44ff' : pu.type === PUP_SHIELD ? '#44aaff' : '#ffaa00';
1573	  ctx.font = `bold ${Math.floor(14*scale)}px "Segoe UI","PingFang SC",sans-serif`;
1574	  ctx.textAlign = 'center';
1575	  ctx.textBaseline = 'middle';
1576	  const ico = pu.type === PUP_MAGNET ? 'M' : pu.type === PUP_SHIELD ? 'S' : 'x2';
