1581	function drawPlayer(ctx) {
1582	  const p = G.player;
1583	  ctx.save();
1584	  ctx.translate(p.x, p.y);
1585	
1586	  /* 无敌闪烁 */
1587	  if (G.invincible > 0 && Math.floor(G.invincible / 4) % 2 === 0) {
1588	    ctx.globalAlpha = 0.4;
1589	  }
1590	
1591	  /* 奔跑时的上下起伏 */
1592	  let bounceY = 0;
1593	  if (p.state === STATE_RUN) {
1594	    bounceY = Math.sin(G.frameCount * 0.4) * 2;
1595	  }
1596	
1597	  /* 阴影 */
1598	  ctx.fillStyle = 'rgba(0,0,0,0.3)';
1599	  ctx.beginPath();
1600	  ctx.ellipse(0, 14, 18, 6, 0, 0, Math.PI * 2);
1601	  ctx.fill();
1602	
1603	  ctx.translate(0, bounceY);
1604	
1605	  const sprite = G.offscreen.player[p.state];
1606	  if (sprite) {
1607	    ctx.drawImage(sprite, -sprite.width/2, -sprite.height/2 + 8);
1608	  }
1609	
1610	  ctx.restore();
1611	}
