1613	/* =========================== HUD =========================== */
1614	function drawHUD(ctx) {
1615	  if (G.state !== 'playing' && G.state !== 'dead') return;
1616	
1617	  /* 左上——血量 */
1618	  const heartSize = 18;
1619	  for (let i = 0; i < MAX_HEARTS; i++) {
1620	    const hx = 16 + i * (heartSize + 6);
1621	    const hy = 16;
1622	    if (i < G.hearts) {
1623	      /* 满血——红色心 */
1624	      drawHeart(ctx, hx, hy, heartSize, '#e94560');
1625	    } else {
1626	      /* 空血——灰色 */
1627	      drawHeart(ctx, hx, hy, heartSize, '#444');
1628	    }
1629	  }
1630	
1631	  /* 顶部居中——分数 */
1632	  ctx.fillStyle = '#fff';
1633	  ctx.font = 'bold 28px "Segoe UI","PingFang SC",sans-serif';
1634	  ctx.textAlign = 'center';
1635	  ctx.shadowColor = 'rgba(0,0,0,0.6)';
1636	  ctx.shadowBlur = 4;
1637	  ctx.fillText(Math.floor(G.score), G.W / 2, 40);
1638	  ctx.shadowBlur = 0;
1639	
1640	  /* 右上——速度指示 */
1641	  const speedPct = Math.floor((G.speed - BASE_SPEED) / (MAX_SPEED - BASE_SPEED) * 100);
1642	  ctx.fillStyle = speedPct > 70 ? '#ff6644' : '#aaccff';
1643	  ctx.font = '12px "Segoe UI","PingFang SC",sans-serif';
1644	  ctx.textAlign = 'right';
1645	  ctx.fillText('速度 ' + speedPct + '%', G.W - 14, 28);
1646	
1647	  /* DEBUG：障碍物/金币统计 */
1648	  let activeObs = 0, activeCoins = 0;
1649	  for (let i = 0; i < G.obstacles.length; i++) if (G.obstacles[i].active) activeObs++;
1650	  for (let i = 0; i < G.coins.length; i++) if (G.coins[i].active) activeCoins++;
1651	  ctx.fillStyle = '#0f0';
1652	  ctx.font = '11px monospace';
1653	  ctx.textAlign = 'left';
1654	  ctx.fillText('DEBUG obs:' + activeObs + ' coins:' + activeCoins + ' dist:' + Math.floor(G.distance) + 'm spawn:' + Math.floor(G.spawnTimer) + '/' + Math.floor(G.spawnInterval/(G.speed/BASE_SPEED)), 12, G.H - 10);
1655	
1656	  /* 道具指示器 */
1657	  const pu = G.player;
1658	  if (pu.activePowerup || pu.hasShield) {
1659	    const puy = 60;
1660	    /* 护盾 */
1661	    if (pu.hasShield) {
1662	      ctx.fillStyle = '#44aaff';
1663	      ctx.font = 'bold 14px "Segoe UI","PingFang SC",sans-serif';
1664	      ctx.textAlign = 'right';
1665	      ctx.fillText('护盾', G.W - 14, puy);
1666	    }
1667	    /* 活动道具计时条 */
1668	    if (pu.activePowerup) {
1669	      const barW = 80, barH = 6;
1670	      const barX = G.W - 14 - barW, barY = puy + 4;
1671	      const pct = pu.powerupTimer / POWERUP_DURATION;
1672	      ctx.fillStyle = 'rgba(255,255,255,0.2)';
1673	      ctx.fillRect(barX, barY, barW, barH);
1674	      const barColor = pu.activePowerup === PUP_MAGNET ? '#ff44ff' :
1675	                       pu.activePowerup === PUP_2X ? '#ffdd00' : '#44aaff';
1676	      ctx.fillStyle = barColor;
1677	      ctx.fillRect(barX, barY, barW * pct, barH);
1678	      /* 标签 */
1679	      const label = pu.activePowerup === PUP_MAGNET ? '磁铁' : '2x分数';
1680	      ctx.fillStyle = '#fff';
1681	      ctx.font = 'bold 12px "Segoe UI","PingFang SC",sans-serif';
1682	      ctx.textAlign = 'right';
