1688	function drawHeart(ctx, x, y, size, color) {
1689	  ctx.fillStyle = color;
1690	  ctx.beginPath();
1691	  const s = size / 20;
1692	  ctx.moveTo(x, y + size * 0.35);
1693	  /* 左半 */
1694	  ctx.bezierCurveTo(x, y + size*0.15, x - size*0.45, y - size*0.15, x - size*0.45, y + size*0.25);
1695	  ctx.bezierCurveTo(x - size*0.45, y + size*0.6, x, y + size*0.8, x, y + size);
1696	  /* 右半 */
1697	  ctx.bezierCurveTo(x, y + size*0.8, x + size*0.45, y + size*0.6, x + size*0.45, y + size*0.25);
1698	  ctx.bezierCurveTo(x + size*0.45, y - size*0.15, x, y + size*0.15, x, y + size*0.35);
1699	  ctx.fill();
1700	}
