1793	function roundRect(ctx, x, y, w, h, r) {
1794	  ctx.beginPath();
1795	  ctx.moveTo(x + r, y);
1796	  ctx.lineTo(x + w - r, y);
1797	  ctx.quadraticCurveTo(x + w, y, x + w, y + r);
1798	  ctx.lineTo(x + w, y + h - r);
1799	  ctx.quadraticCurveTo(x + w, y + h, x + w - r, y + h);
1800	  ctx.lineTo(x + r, y + h);
1801	  ctx.quadraticCurveTo(x, y + h, x, y + h - r);
1802	  ctx.lineTo(x, y + r);
1803	  ctx.quadraticCurveTo(x, y, x + r, y);
1804	  ctx.closePath();
1805	}
