1807	/* =========================== 游戏主循环 =========================== */
1808	function gameLoop(timestamp) {
1809	  G.deltaTime = timestamp - G.lastTime;
1810	  G.lastTime = timestamp;
1811	
1812	  /* FPS 计算 */
1813	  G.frameCount++;
1814	  G.fpsTime += G.deltaTime;
1815	  if (G.fpsTime >= 1000) {
1816	    G.fps = G.frameCount;
1817	    G.frameCount = 0;
1818	    G.fpsTime = 0;
1819	  }
1820	
1821	  processInput();
1822	  update();
1823	  render();
1824	  requestAnimationFrame(gameLoop);
1825	}
